// @generated by:gauntlet run:godseye-e08-independent-gauntlet
import { randomUUID } from "node:crypto";
import { CONTROL_API_HEADER, CONTROL_API_VERSION } from "@godseye/contracts";
import { InfrastructureEngine } from "@godseye/core";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { createApp } from "../apps/control-api/src/app.js";
import { loadConfiguration } from "../apps/control-api/src/config.js";
import { createControlClient } from "../packages/control-client/src/index.js";
import { owner, projectInput } from "./helpers.js";
import { type OwnerAuthFixture, ownerAuthFixture } from "./owner-auth-fixture.js";

describe("E08 authenticated owner HTTP and first-party client", () => {
  let f: OwnerAuthFixture, headers: Headers, infra: InfrastructureEngine;
  beforeEach(async () => {
    f = await ownerAuthFixture();
    headers = (await f.session()).headers;
    headers.set(CONTROL_API_HEADER, CONTROL_API_VERSION);
    infra = new InfrastructureEngine(f.store);
  });
  afterEach(async () => {
    await f.close();
  });
  const app = () =>
    createApp(
      f.core,
      loadConfiguration({ GODSEYE_MODE: "local" }),
      f.identity,
      infra.foundation,
      undefined,
      infra,
    );
  const request = (path: string, method = "GET", body?: unknown, extra: HeadersInit = headers) =>
    app().request(new URL(`/api/v1${path}`, f.origin), {
      method,
      headers: extra,
      ...(body === undefined ? {} : { body: JSON.stringify(body) }),
    });
  const client = () =>
    createControlClient({
      baseUrl: `${f.origin}/api/v1`,
      headers,
      fetch: async (input, init) => app().request(new Request(input, init)),
    });
  it("T-AC-816 authenticates every usage and telemetry boundary before interpreting request bodies", async () => {
    for (const [method, path] of [
      ["GET", "/usage"],
      ["POST", "/usage/prices"],
      ["PUT", "/usage/budgets"],
      ["POST", "/usage/invoices"],
      ["GET", "/observability/health"],
      ["GET", "/observability/logs"],
      ["GET", "/observability/metrics"],
      ["GET", "/observability/timeline"],
      ["POST", "/observability/sources"],
      ["POST", `/observability/sources/${randomUUID()}/records`],
      ["GET", "/overview/operational"],
    ] as const) {
      expect(
        (await request(path, method, method === "GET" ? undefined : {}, f.headers())).status,
      ).toBe(401);
    }
  });
  it("T-AC-816 keeps version negotiation and strict query bounds on the actual HTTP route", async () => {
    const mismatch = new Headers(headers);
    mismatch.set(CONTROL_API_HEADER, "0.0.0");
    expect((await request("/usage", "GET", undefined, mismatch)).status).toBe(422);
    for (const path of [
      "/usage?limit=201",
      "/usage?unknown=authority",
      "/observability/logs?limit=201",
      "/observability/logs?cursor=-1",
    ])
      expect((await request(path)).status).toBe(422);
  });
  it("T-AC-816 rejects CSRF and arbitrary notifier URL fields before creating telemetry sources", async () => {
    const body = {
      name: "synthetic-source",
      authenticatedActorId: "synthetic-service",
      scope: { projectId: null, environmentId: null, resourceId: null },
      kind: "service",
      staleAfterSeconds: 60,
    };
    const crossOrigin = new Headers(headers);
    crossOrigin.set("origin", "https://untrusted.invalid");
    crossOrigin.set("idempotency-key", randomUUID());
    expect((await request("/observability/sources", "POST", body, crossOrigin)).status).toBe(403);
    const validHeaders = new Headers(headers);
    validHeaders.set("idempotency-key", randomUUID());
    expect(
      (
        await request(
          "/observability/sources",
          "POST",
          { ...body, endpoint: "http://127.0.0.1/private" },
          validHeaders,
        )
      ).status,
    ).toBe(422);
    expect((await infra.observability.health(owner)).sources).toHaveLength(0);
  });
  it("T-AC-816 runs typed owner client budget creation replay and CAS through actual HTTP", async () => {
    const project = await f.core.createProject(owner, projectInput, randomUUID());
    const input = {
      projectId: project.id,
      scope: "project" as const,
      scopeId: project.id,
      expectedRevision: 0,
      limitMicros: 10000,
      windowSeconds: 60,
      maxRuns: 10,
      maxConcurrent: 1,
    };
    const key = randomUUID(),
      control = client();
    const first = await control.putUsageBudget(input, key);
    expect(await control.putUsageBudget(input, key)).toEqual(first);
    await expect(
      control.putUsageBudget({ ...input, limitMicros: 10001 }, key),
    ).rejects.toMatchObject({ status: 409, code: "IDEMPOTENCY_CONFLICT" });
    await expect(control.putUsageBudget(input, randomUUID())).rejects.toMatchObject({
      status: 409,
      code: "REVISION_CONFLICT",
    });
    expect((await control.usageOverview({ projectId: project.id })).budgets).toHaveLength(1);
  });
});
